    const f=d=>d.toLocaleDateString('en-US',{month:'short',day:'numeric'});
    const wk=n=>{const d=new Date(mon); d.setDate(d.getDate()+(n-1)*7); return f(d);};
    const base=new Date(now); base.setSeconds(0,0); const anchor=9*3600+17*60; const nowS=base.getHours()*3600+base.getMinutes()*60; const delta=nowS-anchor;
    const shift=t=>{const m=t.match(/^(\d\d):(\d\d)(?::(\d\d))?$/); if(!m) return t; let sec=(+m[1])*3600+(+m[2])*60+(+(m[3]||0))+delta; sec=((sec%86400)+86400)%86400; const h=Math.floor(sec/3600),mi=Math.floor(sec%3600/60),se=sec%60; return `${String(h).padStart(2,'0')}:${String(mi).padStart(2,'0')}`+(m[3]!==undefined?`:${String(se).padStart(2,'0')}`:'');};
